mapper.select:
select TABLE_NAME, TABLE_COMMENT, CREATE_TIME, UPDATE_TIME from information_schema.tables
where TABLE_COMMENT  <>  '' and table_schema = (select database())
  and TABLE_NAME = #{tableName}

mapper.update:
update GEN_TABLE
TABLE_NAME = #{tableName}, TABLE_COMMENT = #{tableComment}, SUB_TABLE_NAME = #{subTableName}, SUB_TABLE_FK_NAME = #{subTableFkName}, CLASS_NAME = #{className}, FUNCTION_AUTHOR = #{functionAuthor}, FORM_COL_NUM = #{formColNum}, GEN_TYPE = #{genType}, GEN_PATH = #{genPath}, TPL_CATEGORY = #{tplCategory}, TPL_WEB_TYPE = #{tplWebType}, PACKAGE_NAME = #{packageName}, MODULE_NAME = #{moduleName}, BUSINESS_NAME = #{businessName}, FUNCTION_NAME = #{functionName}, OPTION_LISTS = #{optionLists}, DESCRIPTION = #{description}, LAST_TIME = sysdate()
where TABLE_ID = #{tableId}
